<script setup lang="ts">
import type { InfoSource } from '../mock'
import { sourceColor } from '../mock'

const props = defineProps<{ sources: InfoSource[]; profile: { nickname: string; email: string; avatar: string } }>()
const emit = defineEmits<{ (event: 'toast', text: string): void }>()
function toggle(source: InfoSource) { source.bound = !source.bound; source.account = source.bound ? `林默 · ${source.name}` : ''; emit('toast', source.bound ? `已绑定${source.name}` : `已解除${source.name}绑定`) }
function save() { emit('toast', '个人资料已保存到本地') }
</script>

